mapper.select:
SELECT ts.id, ts.user_id as userId, u.nick_name as username, ts.selected_glossary_count as selectedGlossaryCount, ts.matched_term_count as matchedTermCount, ts.create_time as createTime FROM translate_statistics ts LEFT JOIN user_account u ON ts.user_id = u.id
AND ts.user_id = #{userId}
ORDER BY ts.create_time DESC
